                nonlocal text_repr
                text_repr = repr_call(test, args, kwargs)

            if print_test_case or current_verbosity() >= Verbosity.verbose:
                printer = RepresentationPrinter(context=context)
                if print_test_case:
                    printer.text("Failing test case:")
                else:
                    printer.text("Test case:")

                if self.print_given_args:
                    printer.text(" ")
                    printer.repr_call(
                        test.__name__,
                        args,
                        kwargs,
                        force_split=True,
                        arg_labels=arglabels,
                        leading_comment=(
                            "# " + context.data.span_comments[None]
                            if None in context.data.span_comments
                            else None
                        ),
                        avoid_realization=data.provider.avoid_realization,
                        known_safe_to_repr=self.known_safe_to_repr,
                    )
                else:
