        elif self._warncount == 1:
            if self._fail_on_warnings:
                self.statuscode = 1
                msg = __('build finished with problems, 1 warning '
                         '(with warnings treated as errors).')
            elif self.statuscode != 0:
                msg = __('build finished with problems, 1 warning.')
            else:
                msg = __('build succeeded, 1 warning.')
            logger.info(bold(msg))
