            except OSError as err:
                logger.warning(
                    __('image file %s not readable: %s'),
                    filename,
                    err,
                    location=node,
                    type='image',
                    subtype='not_readable',
                )
        for key, files in globbed.items():
            candidates[key] = min(files, key=len)  # select by similarity

