        self,
        name: str,
        urls: dict[str, str] | None = None,
        env: BuildEnvironment | None = None,
        graph_attrs: dict[str, float | int | str] | None = None,
        node_attrs: dict[str, float | int | str] | None = None,
        edge_attrs: dict[str, float | int | str] | None = None,
    ) -> str:
